+using System.Text.RegularExpressions;
+using Microsoft.VisualStudio.TestTools.UnitTesting;
+using Contoso.Text;
+
+namespace Contoso.Text.Tests;
+
+[TestClass]
+public sealed class StringFormatterTests
+{
+    private readonly StringFormatter _formatter = new();
+
+    // ── FormatPhoneNumber ──────────────────────────────────────────
+
+    [TestMethod]
+    public void FormatPhoneNumber_ValidDigits_ReturnsFormattedNumber()
+    {
+        var result = _formatter.FormatPhoneNumber("1234567890");
+
+        Assert.AreEqual("(123) 456-7890", result);
+        StringAssert.StartsWith(result, "(");
+        StringAssert.EndsWith(result, "7890");
+        StringAssert.Contains(result, ") ");
+    }
+
+    [TestMethod]
+    public void FormatPhoneNumber_Null_ThrowsArgumentNullException()
+    {
+        Assert.ThrowsException<ArgumentNullException>(
+            () => _formatter.FormatPhoneNumber(null!));
+    }
+
+    [TestMethod]
+    [DataRow("123")]
+    [DataRow("12345678901")]
+    [DataRow("")]
+    public void FormatPhoneNumber_WrongLength_ThrowsArgumentException(string digits)
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _formatter.FormatPhoneNumber(digits));
+    }
+
+    // ── BuildGreeting ──────────────────────────────────────────────
+
+    [TestMethod]
+    public void BuildGreeting_NameOnly_UsesDefaultTitle()
+    {
+        var result = _formatter.BuildGreeting("Smith");
+
+        Assert.AreEqual("Dear Mr. Smith,", result);
+        StringAssert.StartsWith(result, "Dear ");
+        StringAssert.EndsWith(result, ",");
+        StringAssert.Contains(result, "Mr.");
+    }
+
+    [TestMethod]
+    public void BuildGreeting_CustomTitle_UsesProvidedTitle()
+    {
+        var result = _formatter.BuildGreeting("Jones", "Dr.");
+
+        StringAssert.StartsWith(result, "Dear Dr.");
+        StringAssert.EndsWith(result, "Jones,");
+    }
+
+    [TestMethod]
+    [DataRow(null)]
+    [DataRow("")]
+    [DataRow("   ")]
+    public void BuildGreeting_InvalidName_Throws(string? name)
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _formatter.BuildGreeting(name!));
+    }
+
+    // ── GenerateSlug ───────────────────────────────────────────────
+
+    [TestMethod]
+    public void GenerateSlug_SimpleTitle_ReturnsLowercaseSlug()
+    {
+        var result = _formatter.GenerateSlug("Hello World");
+
+        Assert.AreEqual("hello-world", result);
+        StringAssert.Matches(result, new Regex(@"^[a-z0-9\-]+$"));
+    }
+
+    [TestMethod]
+    public void GenerateSlug_SpecialCharacters_ReplacedWithHyphens()
+    {
+        var result = _formatter.GenerateSlug("C# is Great!!!");
+
+        Assert.AreEqual("c-is-great", result);
+    }
+
+    [TestMethod]
+    public void GenerateSlug_LeadingTrailingWhitespace_IsTrimmed()
+    {
+        var result = _formatter.GenerateSlug("  padded title  ");
+
+        Assert.AreEqual("padded-title", result);
+    }
+
+    [TestMethod]
+    [DataRow(null)]
+    [DataRow("")]
+    [DataRow("   ")]
+    public void GenerateSlug_InvalidInput_Throws(string? title)
+    {
+        Assert.ThrowsException<ArgumentException>(
+            () => _formatter.GenerateSlug(title!));
+    }
+
+    // ── FormatCurrency ─────────────────────────────────────────────
+
+    [TestMethod]
+    public void FormatCurrency_DefaultSymbol_PrependsDollarSign()
+    {
+        var result = _formatter.FormatCurrency(9.5m);
+
+        StringAssert.StartsWith(result, "$");
+        StringAssert.EndsWith(result, "9.50");
+        Assert.AreEqual("$9.50", result);
+    }
+
+    [TestMethod]
+    public void FormatCurrency_CustomSymbol_PrependsThatSymbol()
+    {
+        var result = _formatter.FormatCurrency(1234.5m, "€");
+
+        StringAssert.StartsWith(result, "€");
+        Assert.AreEqual("€1234.50", result);
+    }
+
+    [TestMethod]
+    public void FormatCurrency_NegativeAmount_FormatsCorrectly()
+    {
+        var result = _formatter.FormatCurrency(-42.10m);
+
+        StringAssert.StartsWith(result, "$-");
+        StringAssert.EndsWith(result, ".10");
+    }
+
+    [TestMethod]
+    public void FormatCurrency_Zero_ReturnsTwoDecimalPlaces()
+    {
+        var result = _formatter.FormatCurrency(0m);
+
+        Assert.AreEqual("$0.00", result);
+    }
+}
+
